// Firebase configuration
// Use the SAME values as your src/firebase.js
importScripts(
  "https://www.gstatic.com/firebasejs/13.3.0/firebase-app-compat.js",
);

importScripts(
  "https://www.gstatic.com/firebasejs/13.3.0/firebase-messaging-compat.js",
);

// Load configuration generated by Vite
importScripts("/firebase-config.js");

firebase.initializeApp(self.FIREBASE_CONFIG);

const messaging = firebase.messaging();
// Handle background push notifications
messaging.onBackgroundMessage((payload) => {
  console.log("Background message received:", payload);

  const title = payload.data?.title || "CreatorDesk";

  const options = {
    body: payload.data?.body || "You have a new notification.",
    data: {
      url: payload.data?.url || "/",
    },
    tag: payload.data?.tag || "creatordesk-reminder",
  };

  self.registration.showNotification(title, options);
});

// Handle notification clicks
self.addEventListener("notificationclick", (event) => {
  event.notification.close();

  const targetUrl = new URL(
    event.notification.data?.url || "/",
    self.location.origin,
  ).href;

  event.waitUntil(
    clients
      .matchAll({
        type: "window",
        includeUncontrolled: true,
      })
      .then((clientList) => {
        for (const client of clientList) {
          if (client.url.startsWith(self.location.origin)) {
            client.navigate(targetUrl);
            return client.focus();
          }
        }

        return clients.openWindow(targetUrl);
      }),
  );
});
